var values = String(msg.payload).split(",");
var ldrReadings = parseFloat(values[0]);
var dhtReadings = parseFloat(values[1]);
var irReadings = parseInt(values[2]);

if(!irReadings) {
    irReadings = "Object nearby!";
}
else {
    irReadings = "No object nearby..";
}

msg.payload = {
    ldr: ldrReadings,
    dht: dhtReadings,
    ir: irReadings
};

return msg;
